import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        ArrayList<Integer> list = new ArrayList<Integer>();

        int N = scan.nextInt();
        int L = scan.nextInt() - 1;
        int R = scan.nextInt() - 1;

        for (int i = 0; i < N; i++) {
            list.add(i + 1);
        }

        while (L <= R) {
            int comL = list.get(L);    // Store left element temporarily
            int comR = list.get(R);    // Store right element temporarily
            list.set(L, comR);
            list.set(R, comL);
            L++;
            R--;
        }

        for (int i = 0; i < N; i++) {
            System.out.print(list.get(i) + " ");
        }

        scan.close();
    }
}
